function value(text,name,labels) {
 const lines=text.split("\n");
 for(const line of lines) {
  if(!line.startsWith(name+"{") && !line.startsWith(name+" ")) continue;
  const match=line.match(/^([^ {]+)(?:\{(.*)\})?\s+([^ ]+)/);
  if(!match || match[1]!==name) continue;
  if(Object.keys(labels).every(key=>(match[2]||"").includes(key+'="'+labels[key]+'"'))) return Number(match[3]);
 }
 throw new Error("Missing metric "+name+" "+JSON.stringify(labels));
}
function send(path) {
 return new Promise(resolve=>pm.sendRequest(base+path,function(err,res){
  if(err) resolve({status:0,text:""}); else resolve({status:res.code,text:res.text()});
 }));
}

