(async function(){
 const labels={service:"users",priority:"critical"};
 const completed={service:"users",priority:"critical",outcome:"completed"};
 const before=pm.response.text();
 const hello=await send("/users/hello");
 const after=(await send("/metrics")).text;
 pm.test("Successful handler increments admissions and latency count once",function(){
  pm.expect(hello.status).to.eql(200);
  pm.expect(value(after,"gatewise_requests_admitted_total",labels)).to.eql(value(before,"gatewise_requests_admitted_total",labels)+1);
  pm.expect(value(after,"gatewise_request_duration_seconds_count",completed)).to.eql(value(before,"gatewise_request_duration_seconds_count",completed)+1);
 });
 const again=(await send("/metrics")).text;
 pm.test("Scraping does not count as application traffic",function(){pm.expect(value(again,"gatewise_requests_admitted_total",labels)).to.eql(value(after,"gatewise_requests_admitted_total",labels));});
 const held=send("/users/background/slow?delay=750ms");
 const bg={service:"users",priority:"background"};
 let busy=null;
 for(let i=0;i<20;i++) {
  const scrape=await send("/metrics");
  if(value(scrape.text,"gatewise_requests_in_flight",bg)===1){busy=scrape.text;break;}
  await new Promise(resolve=>setTimeout(resolve,10));
 }
 if(busy===null) throw new Error("Did not observe background work in flight");
 const rejected=await send("/users/background/hello");
 const blocked=(await send("/metrics")).text;
 const reason={service:"users",priority:"background",reason:"critical_capacity_reserved"};
 const bgCompleted={service:"users",priority:"background",outcome:"completed"};
 pm.test("In-flight gauge exposes admitted work during saturation",function(){pm.expect(value(busy,"gatewise_requests_in_flight",bg)).to.eql(1);});
 pm.test("Rejection increments its reason counter without becoming a latency sample",function(){
  pm.expect(rejected.status).to.eql(503);
  pm.expect(value(blocked,"gatewise_requests_rejected_total",reason)).to.eql(value(busy,"gatewise_requests_rejected_total",reason)+1);
  pm.expect(value(blocked,"gatewise_request_duration_seconds_count",bgCompleted)).to.eql(value(busy,"gatewise_request_duration_seconds_count",bgCompleted));
 });
 pm.test("Metrics remain available while background capacity is full",function(){pm.expect(blocked).to.include("gatewise_concurrency_limit");});
 await held;
 const ended=(await send("/metrics")).text;
 pm.test("Completion clears active work and adds one handler-duration sample",function(){
  pm.expect(value(ended,"gatewise_requests_in_flight",bg)).to.eql(0);
  pm.expect(value(ended,"gatewise_request_duration_seconds_count",bgCompleted)).to.eql(value(busy,"gatewise_request_duration_seconds_count",bgCompleted)+1);
 });
})().catch(function(err){pm.test("Metrics accounting scenario completes",function(){throw err;});});

