const minimum=Number(pm.environment.get("adaptive_min"));
const maximum=Number(pm.environment.get("adaptive_max"));
const healthy=Number(pm.environment.get("adaptive_healthy_delay_ms"));
const slow=Number(pm.environment.get("adaptive_slow_delay_ms"));
const base=pm.environment.get("adaptive_proxy_url");
const fixedURL=base+"/catalog/hello";
if (!Number.isInteger(minimum) || !Number.isInteger(maximum) || minimum<2 || maximum<=minimum || maximum>16) throw new Error("M4 demo requires 2 <= adaptive_min < adaptive_max <= 16, matching server configuration.");
function send(url) {
 return new Promise(resolve=>pm.sendRequest(url,function(err,res){
  let body={};if(res){try{body=res.json();}catch(_){}}
  resolve({body:body,status:err ? 0 : res.code,limit:res ? Number(res.headers.get("X-Gatewise-Limit")) : 0,mode:res ? res.headers.get("X-Gatewise-Mode") : ""});
 }));
}
const observed=[];
async function batch(path) {
 const results=await Promise.all(Array.from({length:maximum+2},()=>send(base+path)));
 const probe=await send(base+"/users/hello");
 for(const r of results.concat([probe])) {
  if (![200,503].includes(r.status) || r.mode!=="adaptive" || r.limit<minimum || r.limit>maximum) throw new Error("Unexpected status/mode/limit: "+JSON.stringify(r));
  observed.push(r.limit);
 }
 return probe.limit;
}
async function drive(path,wanted) {
 const deadline=Date.now()+15000;
 while(Date.now()<deadline) {
  const limit=await batch(path);
  if (limit===wanted) return limit;
  await new Promise(resolve=>setTimeout(resolve,25));
 }
 throw new Error("Controller did not reach "+wanted+"; observed "+JSON.stringify(observed));
}
(async function(){
 const before=await send(fixedURL);
 pm.test("Reference service stays in fixed mode",function(){pm.expect(before.status).to.eql(200);pm.expect(before.mode).to.eql("fixed");});
 const warm=await drive("/users/slow?delay="+healthy+"ms",maximum);
 pm.test("Healthy saturated work grows to the configured ceiling",function(){pm.expect(warm).to.eql(maximum);});
 const reportLimits=[];
 for(let i=0;i<4;i++) reportLimits.push(await batch("/users/reports/slow?delay="+slow+"ms"));
 pm.test("Slow handler within its own latency budget does not reduce shared capacity",function(){reportLimits.forEach(n=>pm.expect(n).to.eql(maximum));});
 const reduced=await drive("/users/slow?delay="+slow+"ms",minimum);
 pm.test("Latency pressure reduces admission to the bounded minimum",function(){pm.expect(reduced).to.eql(minimum);pm.expect(reduced).to.be.below(warm);});
 const heldBackground=send(base+"/users/background/slow?delay="+slow+"ms");
 let rejectedBackground=null;
 for(let i=0;i<20;i++) {
  const r=await send(base+"/users/background/hello");
  if(r.status===503 && r.body.reason==="critical_capacity_reserved") {rejectedBackground=r;break;}
  await new Promise(resolve=>setTimeout(resolve,10));
 }
 pm.test("Critical reservation still holds at the adaptive minimum",function(){pm.expect(rejectedBackground).to.not.eql(null);});
 const criticalAtMin=await send(base+"/users/hello");
 pm.test("Reserved critical work remains available at the adaptive minimum",function(){pm.expect(criticalAtMin.status).to.eql(200);});
 await heldBackground;
 const recovered=await drive("/users/slow?delay="+healthy+"ms",maximum);
 pm.test("Healthy sustained traffic recovers capacity",function(){pm.expect(recovered).to.eql(maximum);pm.expect(recovered).to.be.above(reduced);});
 pm.test("All observed limits stay within bounds",function(){observed.forEach(n=>pm.expect(n).to.be.within(minimum,maximum));});
 const after=await send(fixedURL);
 pm.test("Adaptive changes do not alter the fixed reference",function(){pm.expect(after.status).to.eql(200);pm.expect(after.limit).to.eql(before.limit);pm.expect(after.mode).to.eql("fixed");});
 console.log("M4 phases: "+JSON.stringify({warm:warm,reduced:reduced,recovered:recovered}));
 console.log("M4 observed limits: "+JSON.stringify(observed));
})().catch(function(err){pm.test("Adaptive scenario completes",function(){throw err;});});

